sample.code:
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ofstream out("marks.txt");
    if (!out) {
        cout << "Cannot open marks.txt" << endl;
        return 1;
    }
    out << "Ali" << endl;
    out << 78 << endl;
    out << "Sana " << 91.5 << endl;
    out.close();

    ifstream in("marks.txt");
    string line;
    while (getline(in, line)) {
        cout << line << endl;
    }
    in.close();
    return 0;
}

#include <iostream>
#include <fstream>
#include <string>
using namespace std;

void show(string name) {
    ifstream in(name);
    string line;
    while (getline(in, line)) {
        cout << "  " << line << endl;
    }
}

int main() {
    ofstream a("log.txt");
    a << "run 1" << endl;
    a.close();
    cout << "After first write:" << endl;
    show("log.txt");

    ofstream b("log.txt");
    b << "run 2" << endl;
    b.close();
    cout << "After writing again:" << endl;
    show("log.txt");

    ofstream c("log.txt", ios::app);
    c << "run 3" << endl;
    c.close();
    cout << "After appending:" << endl;
    show("log.txt");
    return 0;
}

#include <iostream>
#include <fstream>
#include <string>
using namespace std;

struct Student {
    int roll;
    string name;
    double marks;
};

int main() {
    Student s[3] = { {101, "Ali", 78.5}, {102, "Sana", 91}, {103, "Usman", 66.25} };

    ofstream out("students.txt");
    if (!out) {
        cout << "Cannot open students.txt" << endl;
        return 1;
    }
    out << "Roll Name Marks" << endl;
    for (int i = 0; i < 3; i++) {
        out << s[i].roll << " " << s[i].name << " " << s[i].marks << endl;
    }
    out.close();

    ifstream in("students.txt");
    string line;
    while (getline(in, line)) {
        cout << line << endl;
    }
    in.close();
    return 0;
}

