#include <iostream>
#include <fstream>
#include <string>
using namespace std;
int main() {
    double p[3] = {12.5, 40, 7.75};
    ofstream out("prices.txt");
    if (!out) { cout << "Cannot open prices.txt" << endl; return 1; }
    for (int i = 0; i < 3; i++)
        out << p[i] << endl;
    out.close();
    ifstream in("prices.txt");
    string line;
    while (getline(in, line))
        cout << line << endl;
    in.close();
    return 0;
}
